## Why This Is Asked
This question tests the ability to design a practical data structure and reason about block balancing in edit-heavy scenarios.

## Key Concepts
- **Sqrt decomposition**: Partition data into fixed-size blocks for efficient range queries
- **Per-block sums**: Enable O(1) block-level aggregation during rangeSum operations
- **Amortized balance**: Split/merge operations maintain block sizes within bounds, ensuring O(√n) amortized time per update
- **Edge-case handling**: Proper merge/split logic prevents pathological degradation

## Code Example
```javascript
class SqrtArray {
  constructor() {
    this.blocks = [];
    this.B = 2;
  }

  _getBlock(index) {
    let count = 0;
    for (const block of this.blocks) {
      if (index < count + block.length) return block;
      count += block.length;
    }
    throw new Error('Index out of bounds');
  }

  insertAt(index, value) {
    const block = this._getBlock(index);
    block.push(value);
    block.sum += value;
    if (block.length > 2 * this.B) this._split(block);
  }

  eraseAt(index) {
    const block = this._getBlock(index);
    block.splice(index, 1);
    block.sum -= value;
    if (block.length < this.B / 2) this._merge(block);
  }

  rangeSum(l, r) {
    let sum = 0;
    let count = 0;
    for (const block of this.blocks) {
      const blockStart = count;
      const blockEnd = count + block.length - 1;
      if (r < blockStart || l > blockEnd) { count += block.length; continue; }
      const start = Math.max(l, blockStart);
      const end = Math.min(r, blockEnd);
      if (start === blockStart && end === blockEnd) sum += block.sum;
      else for (let i = start; i <= end; i++) sum += block[i];
      count += block.length;
    }
    return sum;
  }

  _split(block) {
    const mid = Math.floor(block.length / 2);
    const newBlock = { arr: block.arr.splice(mid), sum: newBlock.arr.reduce((a,b)=>a+b,0) };
    block.sum = block.arr.reduce((a,b)=>a+b,0);
    const idx = this.blocks.indexOf(block);
    this.blocks.splice(idx + 1, 0, newBlock);
  }

  _merge(block) {
    const idx = this.blocks.indexOf(block);
    const neighbor = idx > 0 ? this.blocks[idx - 1] : this.blocks[idx + 1];
    const [small, big] = neighbor.length > block.length ? [block, neighbor] : [neighbor, block];
    big.arr.push(...small.arr);
    big.sum += small.sum;
    this.blocks.splice(this.blocks.indexOf(small), 1);
  }
}
```

## Why This Is Asked
Tests ability to design a compact, efficiently updatable structure for interval coverage with duplicates, a common real-world requirement in analytics and scheduling.

## Key Concepts
- Coordinate compression for endpoints and end+1 values
- Fenwick tree (BIT) for range-add / point-query
- Multiset tracking for (l,r) duplicates
- Edge-case handling: removing non-existent intervals, empty structures

## Code Example
```javascript
class Fenwick {
  constructor(n){ this.n=n; this.f=new Array(n+2).fill(0); }
  add(i, delta){ for(; i<=this.n; i+=i&-i) this.f[i]+=delta; }
  sum(i){ let s=0; for(; i>0; i-=i&-i) s+=this.f[i]; return s; }
}
class IntervalCoverage {
  constructor(coords){ // coords: sorted unique endpoints and endpoints+1
    this.coords = coords;
    this.bit = new Fenwick(coords.length+2);
    this.cnt = new Map(); // key "l,r" -> count of such intervals
  }
  idx(v){ // 1-based index for v in coords (assumes v is present)
    let l=0, r=this.coords.length; while(l<r){ const m=(l+r)>>1; if(this.coords[m] >= v) r=m; else l=m+1; } return l+1;
  }
  addInterval(l,r){ const key=`${l},${r}`; this.cnt.set(key, (this.cnt.get(key)||0)+1);
    this.bit.add(this.idx(l), +1);
    this.bit.add(this.idx(r+1), -1);
  }
  removeInterval(l,r){ const key=`${l},${r}`; const c=(this.cnt.get(key)||0); if(c<=0) return; this.cnt.set(key, c-1);
    this.bit.add(this.idx(l), -1);
    this.bit.add(this.idx(r+1), +1);
  }
  queryCoverage(x){ return this.bit.sum(this.idx(x)); }
}
```

